/**
 * General sprints shown across the Navigating Sprints and Explore Sprints mockups.
 * Codes use the SPR- prefix (type-template agents use their own prefixes).
 * Idempotent: rows are matched on code. Order is stable — append new rows at the end.
 */
class SprintsCatalogueSeeder extends Seeder
{
    public function run(): void
    {
        foreach (self::specs() as $i => $spec) {
            $code = sprintf('SPR-%04d', $i + 1);
            Sprint::updateOrCreate(['code' => $code], SprintContent::build($spec));
        }
    }

